func RenderTitledRule(title string, width int) string {
	borderStyle := lipgloss.NewStyle().
		Foreground(ColorViewportBorder).
		Background(ColorBackground)
	titleStyle := lipgloss.NewStyle().
		Foreground(ColorTitleFg).
		Background(ColorBackground).
