117		// T-junctions so the two form one closed rectangle.
118		if view, ok := a.views[a.currentView]; ok {
119			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
120				body = replaceViewportBottomCorners(body)
121			}
122		}
123		return body
124	}
125	
126	// renderTitleLine draws the viewport's top border carrying the view's title —
127	// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
128	// reader oriented where a top border would draw the top of a nonexistent box.
129	func (a *App) renderTitleLine() string {
130		title := ""
131		if view, ok := a.views[a.currentView]; ok {
132			if hv, implements := view.(HeaderView); implements {
133				title = hv.GetTitle()
134			}
135		}
136		if a.frameless() {
137			return theme.RenderTitledRule(title, a.width)
138		}
139		return theme.RenderBorderTitle(title, a.width)
140	}
141	
142	// frameless reports whether the active view draws its own frames (see
143	// FramelessView). The default is framed.
144	func (a *App) frameless() bool {
145		view, ok := a.views[a.currentView]
146		if !ok {
147			return false
148		}
149		fv, implements := view.(FramelessView)
150		return implements && fv.Frameless()
151	}
152	
153	// renderViewFooter returns the active view's footer, or "" when it has none.
154	func (a *App) renderViewFooter() string {
155		if view, ok := a.views[a.currentView]; ok {
156			if fv, ok := view.(FooterView); ok {
157				return fv.RenderFooter(a.width)
158			}
159		}
160		return ""
161	}
162	
163	// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
164	// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
165	// the border into one closed rectangle instead of two stacked boxes.
166	func replaceViewportBottomCorners(body string) string {
167		lastNewline := strings.LastIndex(body, "\n")
168		if lastNewline == -1 {
169			return body
170		}
171		lastLine := body[lastNewline+1:]
172		lastLine = strings.Replace(lastLine, "└", "├", 1)
173		lastLine = strings.Replace(lastLine, "┘", "┤", 1)
174		return body[:lastNewline+1] + lastLine
175	}
