1	package agentusageview
2	
3	import (
4		"fmt"
5		"path/filepath"
6		"strconv"
7		"strings"
8	
9		"github.com/charmbracelet/lipgloss"
10	
11		"github.com/anthnel/devdesk/internal/agentusage/pricing"
12		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
13		"github.com/anthnel/devdesk/internal/ui/shortcut"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	// baseFooterHeight is the blank line and the message line (Rule 124).
18	const baseFooterHeight = 2
19	
20	// View is the table, whatever it holds (Rule 139).
21	func (m Model) View() string {
22		if m.onBreakdown() {
23			return m.breakdownWindow()
24		}
25		if m.level == levelAgents {
26			return m.agentTable.View()
27		}
28		return m.table.View()
29	}
30	
31	// minTableLines is what datatable renders at the shortest: the header and at
32	// least one row. The panel takes the same floor so both tabs have one height.
33	const minTableLines = 2
34	
35	// breakdownWindow is the part of the panel on screen: exactly the height of the
36	// table's zone, so the viewport border does not move between tabs.
37	func (m Model) breakdownWindow() string {
38		h := m.panelHeight()
39		lines := m.breakdownLines()
40		top := clampTop(m.breakdownTop, len(lines), h)
41		window := append([]string(nil), lines[top:min(top+h, len(lines))]...)
42		for len(window) < h {
43			window = append(window, theme.EmptyLineBg(max(m.width-2, 0)))
44		}
45		return strings.Join(window, "\n")
46	}
47	
48	// panelHeight is the number of panel lines on screen: the table's height, with
49	// the table's floor. Scrolling and drawing both read it.
50	func (m Model) panelHeight() int { return max(m.height, minTableLines) }
51	
52	// GetTitle names the view, and the project of the open session at the agents
53	// level (its short ID when the transcript named no project).
54	func (m Model) GetTitle() string {
55		title := theme.IconAgentUsage + " Agent usage"
56		if m.level != levelAgents {
57			return title
58		}
59		leaf := shortID(m.open.ID)
60		if m.open.Project != "" {
61			leaf = filepath.Base(m.open.Project)
62		}
63		return title + " › " + leaf
64	}
65	
66	// shortID is the start of a session ID, as the Session column shows it.
67	func shortID(id string) string {
68		r := []rune(id)
69		return string(r[:min(sessionIDPrefix, len(r))])
70	}
71	
72	// GetIcon returns nothing: the title carries the icon.
73	func (m Model) GetIcon() string { return "" }
74	
75	// GetHeaderInfo counts the sessions on screen, and the ones not listed when
76	// there are some.
77	func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
78		if m.level == levelAgents {
79			return m.agentsHeaderInfo()
80		}
81		info := []shortcut.HeaderInfo{
82			{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
83		}
84		if m.omitted > 0 {
85			info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
86		}
87		return info
88	}
89	
90	// headerRows are the rows the agents header counts: the visible ones on Agents,
91	// every row on Breakdown, whose panel covers the whole session.
92	func (m Model) headerRows() []agentRow {
93		if m.tab == tabBreakdown {
94			return m.agentTable.Items()
95		}
96		return m.agentTable.Visible()
97	}
98	
99	// agentsHeaderInfo counts the agents and their tokens: following the filter on
100	// Agents, the whole session on Breakdown.
101	func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
102		rows := m.headerRows()
103		var total int64
104		estimates := make([]pricing.Estimate, len(rows))
105		for i, r := range rows {
106			total += r.Tokens.Total()
107			estimates[i] = r.cost
108		}
109		info := []shortcut.HeaderInfo{
110			{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
111			{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
112			{Key: "Est. cost", Value: estCostValue(pricing.Sum(estimates)), Style: theme.HeaderValueStyle},
113		}
114		info = append(info, m.billedHeaderInfo()...)
115		info = append(info, shortcut.HeaderInfo{Key: "Updates", Value: m.updatesState(), Style: theme.HeaderValueStyle})
116		if n := m.idleCount(); n > 0 {
117			info = append(info, shortcut.HeaderInfo{Key: "Idle", Value: strconv.Itoa(n), Style: theme.HeaderValueStyle})
118		}
119		return info
120	}
121	
122	// negativeUSD is half a cent: an Unattributed amount at or below its negative
123	// shows as -$0.01 or lower, so only then is the price table "above the bill".
124	// Float noise (-1e-12) renders $0.00 and must not look stale.
125	const negativeUSD = 0.005
126	
127	// billedHeaderInfo is Billed and Unattributed, both facts of the whole session
128	// that ignore the filter. Neither shows while Claude Code has not recorded a
129	// bill. Unattributed is a dash when an agent has no price, and a negative one
130	// (the price table is above what was billed) is orange.
131	func (m Model) billedHeaderInfo() []shortcut.HeaderInfo {
132		if !m.cost.Billed.Known {
133			return nil
134		}
135		unattributed := shortcut.HeaderInfo{Key: "Unattributed", Value: noValue, Style: theme.HeaderValueStyle}
136		if m.cost.UnattributedKnown {
137			unattributed.Value = formatUSD(m.cost.Unattributed)
138			if m.cost.Unattributed <= -negativeUSD {
139				unattributed.Style = theme.HeaderWarnValueStyle()
140			}
141		}
142		return []shortcut.HeaderInfo{
143			{Key: "Billed", Value: formatUSD(m.cost.Billed.USD), Style: theme.HeaderValueStyle},
144			unattributed,
145		}
146	}
147	
148	// estCostValue is the Est. cost header value: an estimate, or a dash when the
149	// sum is unknown or there is nothing to price.
150	func estCostValue(e pricing.Estimate) string {
151		if e.Status != pricing.Priced {
152			return noValue
153		}
154		return estimateMark + formatUSD(e.USD)
155	}
156	
157	// idleCount counts the idle agents over every row, not just the visible ones:
158	// an alert must not hide behind a filter.
159	func (m Model) idleCount() int {
160		n := 0
161		for _, r := range m.agentTable.Items() {
162			if r.state == stateIdle {
163				n++
164			}
165		}
166		return n
167	}
168	
169	// updatesState says whether the open session is polled: live while the chain
170	// runs, paused once it stopped (settled session, deleted transcript).
171	func (m Model) updatesState() string {
172		if m.level == levelAgents && m.agg != nil && !m.pollStopped {
173			return "live"
174		}
175		return "paused"
176	}
177	
178	// GetShortcuts returns the same keys at both levels and in every state; what
179	// varies is Disabled, from the one availability the handlers also read
180	// (Rule 130).
181	func (m Model) GetShortcuts() shortcut.Shortcuts {
182		a := m.availability()
183		return shortcut.Shortcuts{
184			{Key: "ctrl+r", Description: "Refresh"},
185			{Key: "→", Description: "Open agents", Disabled: !a.Open.Enabled()},
186			{Key: "esc", Description: "Go back", Disabled: !a.Close.Enabled()},
187			{Key: "tab", Description: "Switch tab", Disabled: !a.Tab.Enabled()},
188			{Key: "/", Description: "Filter", Disabled: !a.Filter.Enabled()},
189			{Key: ".", Description: "Sort", Disabled: !a.Sort.Enabled()},
190			{Key: "?", Description: "Help"},
191		}
192	}
193	
194	// GetFooterHeight budgets the footer (Rules 124, 136).
195	func (m Model) GetFooterHeight() int {
196		h := baseFooterHeight
197		if bar := m.activeFilterBar(); bar != nil {
198			h += bar.ExtraHeight()
199		}
200		if m.level == levelAgents {
201			h += 2 // the breadcrumb row and the tab row
202		}
203		return h
204	}
205	
206	// RenderFooter renders, top to bottom: the filter bar when visible (it closes
207	// the viewport's rectangle, Rule 136), at the agents level the breadcrumb and
208	// the tab row, a blank line, and the message line.
209	func (m Model) RenderFooter(width int) string {
210		line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
211		if m.level == levelAgents {
212			line = m.breadcrumb(width) + "\n" + m.tabRow(width) + "\n" + line
213		}
214		if bar := m.activeFilterBar(); bar != nil && bar.IsVisible() {
215			line = bar.View() + "\n" + line
216		}
217		return line
218	}
219	
220	// tabRow is the Agents / Breakdown tabs, the active one marked, with the one
221	// cell of left padding Rule 123 asks for.
222	func (m Model) tabRow(width int) string {
223		tabs := []theme.TabItem{{Label: "Agents"}, {Label: "Breakdown"}}
224		return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, int(m.tab)), width)
225	}
226	
227	// breadcrumb is Sessions › project › ID, the last one active and its parents
228	// dim, with the one cell of left padding Rule 123 asks for.
229	func (m Model) breadcrumb(width int) string {
230		project := noProject
231		if m.open.Project != "" {
232			project = theme.ShortPath(m.open.Project, max(width/2, 1))
233		}
234		base := lipgloss.NewStyle().Background(theme.ColorBackground)
235		parents := base.Foreground(theme.ColorDim).Render("Sessions › " + project + " › ")
236		active := base.Foreground(theme.ColorSecondary).Bold(true).Render(shortID(m.open.ID))
237		return theme.PadWithBg(theme.Bg(" ")+parents+active, width)
238	}
239	
240	// status is derived on every frame, with no timer (Rule 128).
241	//
242	// The empty sentence needs the listing to be empty in total, not after the
243	// filter: a filter with no match is not a machine with no sessions.
244	func (m Model) status() sharedcomponents.Status {
245		if m.level == levelAgents {
246			return m.agentsStatus()
247		}
248		switch {
249		case m.loadErr:
250			return sharedcomponents.Status{
251				Text:  "Failed to list Claude Code sessions — check logs",
252				Level: sharedcomponents.LevelError,
253			}
254		case m.loading:
255			return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
256		case len(m.table.Items()) == 0:
257			return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
258		}
259		return sharedcomponents.Status{}
260	}
261	
262	// agentsStatus is the footer state of the agents level.
263	func (m Model) agentsStatus() sharedcomponents.Status {
264		switch {
265		case m.agentsErr:
266			return sharedcomponents.Status{
267				Text:  "Failed to read this session — check logs",
268				Level: sharedcomponents.LevelError,
269			}
270		case m.agentsLoading:
271			return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
272		case m.usage.Diagnostics.Degraded():
273			return sharedcomponents.Status{
274				Text:  "Totals are approximate — some transcript data could not be read",
275				Level: sharedcomponents.LevelWarning,
276			}
277		}
278		return m.priceHint()
279	}
280	
281	// priceHint is the footer state about missing prices: where to set them when
282	// the table is empty, which model lacks one otherwise. It is a state derived on
283	// every frame, not a message (Rule 128).
284	func (m Model) priceHint() sharedcomponents.Status {
285		if m.prices.Len() == 0 {
286			if m.usage.Total().Total() == 0 {
287				return sharedcomponents.Status{}
288			}
289			return sharedcomponents.Status{Text: "Set agent_usage.prices in this context's config file to estimate costs — see ?"}
290		}
291		switch n := len(m.cost.Unpriced); n {
292		case 0:
293			return sharedcomponents.Status{}
294		case 1:
295			return sharedcomponents.Status{Text: "No price for " + m.cost.Unpriced[0] + " in agent_usage.prices — its cost shows -"}
296		default:
297			return sharedcomponents.Status{Text: fmt.Sprintf(
298				"No price for %s and %d more models in agent_usage.prices — their cost shows -", m.cost.Unpriced[0], n-1)}
299		}
300	}
