1	package app
2	
3	import (
4		"strings"
5	
6		"github.com/anthnel/devdesk/internal/ui/shortcut"
7		"github.com/anthnel/devdesk/internal/ui/theme"
8		"github.com/charmbracelet/lipgloss"
9		"github.com/charmbracelet/x/ansi"
10	)
11	
12	// HeaderView is the interface each view must implement to provide the header data
13	type HeaderView interface {
14		GetShortcuts() shortcut.Shortcuts
15		GetTitle() string
16		GetIcon() string
17		GetHeaderInfo(context string) []shortcut.HeaderInfo
18	}
19	
20	// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
21	// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
22	type FooterView interface {
23		GetFooterHeight() int          // current footer height in lines (0 if no footer)
24		RenderFooter(width int) string // rendered footer content
25	}
26	
27	// FramelessView is implemented by a view that draws its own frames and wants
28	// none around it. The default — framed — is the safe behavior: a view that
29	// does not implement this is framed like all the others, unlike HeaderView
30	// whose missing half silently renders an empty title.
31	//
32	// Only one view implements it (the dashboard), and that is deliberate: every
33	// other view frames a single object — a table, a form.
34	type FramelessView interface {
35		Frameless() bool
36	}
37	
38	// headerMinHeight is the fixed header height (without the blank line under it).
39	const headerMinHeight = 7
40	
41	// ASCII logo for the header
42	var logoLines = []string{
43		`    ____            ____            __  `,
44		`   / __ \___ _   __/ __ \___  _____/ /__`,
45		`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
46		` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
47		`/_____/\___/|___/_____/\___/____/_/|_|  `,
48	}
49	
50	const logoWidth = 40 // max width of a logo line
51	
52	// paletteHintText is the permanent header hint that advertises the command palette
53	// (DEVDESK-109). It sits on the header's last row, flush right.
54	const paletteHintText = "ctrl+p Commands"
55	
56	// renderHeader generates the header (fixed height) and the blank line under it.
57	// The command palette is an overlay (DEVDESK-109): it adds no row here.
58	func (a *App) renderHeader() string {
59		if view, ok := a.views[a.currentView]; ok {
60			if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
61				shortcuts := headerView.GetShortcuts()
62				if a.commandMode {
63					shortcuts = a.commandLineShortcuts()
64				}
65				info := headerView.GetHeaderInfo(a.currentContext)
66	
67				return renderHeaderContent(info, shortcuts, a.width) + "\n" + theme.EmptyLineBg(a.width)
68			}
69		}
70	
71		return ""
72	}
73	
74	// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
75	// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
76	func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
77		// Two padding cells are the minimum a row can hold; below that the header
78		// is blank rather than wider than the window.
79		if width < 2 {
80			return strings.Join(blankHeaderRows(width), "\n")
81		}
82		innerWidth := width - 2 // 1 padding each side
83	
84		// Column widths
85		col1Width := innerWidth / 4
86		col3Width := logoWidth
87		// The logo column is fixed-width: drop it when it cannot sit next to the
88		// info column, rather than pushing every row past the window (Rule 108).
89		if innerWidth < col1Width+logoWidth {
90			col3Width = 0
91		}
92		col2Width := innerWidth - col1Width - col3Width
93		if col2Width < 0 {
94			col2Width = 0
95		}
96	
97		// Build column 1: key-value info lines
98		col1Lines := buildInfoLines(info, col1Width)
99	
100		// Build column 2: shortcuts
101		col2Lines := buildShortcutLines(shortcuts, col2Width)
102	
103		// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
104		var col3Lines []string
105		if col3Width > 0 {
106			col3Lines = buildLogoLines(col3Width)
107		}
108	
109		// Assemble rows
110		rows := make([]string, headerMinHeight)
111		for i := 0; i < headerMinHeight; i++ {
112			c1 := ""
113			if i < len(col1Lines) {
114				c1 = col1Lines[i]
115			}
116			c2 := ""
117			if i < len(col2Lines) {
118				c2 = col2Lines[i]
119			}
120			c3 := ""
121			if i < len(col3Lines) {
122				c3 = col3Lines[i]
123			}
124	
125			pad := theme.Bg(" ")
126			if i == headerMinHeight-1 {
127				// The hint takes the right end of the shortcut and logo columns.
128				rows[i] = pad + theme.PadWithBg(c1, col1Width) + withPaletteHint(c2, col2Width+col3Width, col2Width) + pad
129				continue
130			}
131			row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
132			rows[i] = row
133		}
134	
135		return strings.Join(rows, "\n")
136	}
137	
138	// withPaletteHint returns a line of exactly width cells: shortcuts on the left,
139	// the palette hint flush right. The shortcuts are clipped to maxShortcuts cells
140	// and to what the hint leaves free; ansi.Truncate cuts on cell boundaries and
141	// never inside an escape sequence.
142	func withPaletteHint(shortcuts string, width, maxShortcuts int) string {
143		hint := ansi.Truncate(theme.ShortcutHintStyle.Render(paletteHintText), width, "")
144		free := min(maxShortcuts, width-lipgloss.Width(hint)-1)
145		if free < 0 {
146			free = 0
147		}
148		left := ansi.Truncate(shortcuts, free, "")
149		gap := width - lipgloss.Width(left) - lipgloss.Width(hint)
150		return left + theme.EmptyLineBg(gap) + hint
151	}
152	
153	// blankHeaderRows returns headerMinHeight background-filled rows of the given width.
154	func blankHeaderRows(width int) []string {
155		rows := make([]string, headerMinHeight)
156		for i := range rows {
157			rows[i] = theme.EmptyLineBg(width)
158		}
159		return rows
160	}
161	
162	// buildInfoLines builds the key-value info lines for column 1, aligning values on the longest key.
163	// Lines wider than col1Width are clipped, so a narrow column never overflows into the next one.
164	func buildInfoLines(info []shortcut.HeaderInfo, col1Width int) []string {
165		// Find max key length for alignment
166		maxKeyLen := 0
167		for _, h := range info {
168			if len(h.Key) > maxKeyLen {
169				maxKeyLen = len(h.Key)
170			}
171		}
172	
173		lines := make([]string, headerMinHeight)
174		for i := 0; i < headerMinHeight; i++ {
175			if i < len(info) {
176				// Pad key to maxKeyLen so all ": " align
177				paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
178				label := theme.HeaderKeyStyle.Render(paddedKey + ": ")
179	
180				value := info[i].Value
181				if info[i].Style.GetForeground() != lipgloss.Color("") {
182					value = info[i].Style.Background(theme.ColorBackground).Render(value)
183				} else {
184					value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
185				}
186	
187				lines[i] = label + value
188				if col1Width > 0 {
189					// MaxWidth truncates on rune boundaries and keeps escape sequences intact.
190					lines[i] = lipgloss.NewStyle().MaxWidth(col1Width).Render(lines[i])
191				} else {
192					// No room at all: show nothing rather than overflow.
193					lines[i] = ""
194				}
195			} else {
196				lines[i] = ""
197			}
198		}
199		return lines
200	}
201	
202	// buildShortcutLines builds the shortcut lines for column 2
203	func buildShortcutLines(shortcuts shortcut.Shortcuts, col2Width int) []string {
204		// A column with no width shows no shortcut: PadWithBg returns a long line
205		// untouched, so anything rendered here would spill past the window.
206		if len(shortcuts) == 0 || col2Width <= 0 {
207			lines := make([]string, headerMinHeight)
208			for i := range lines {
209				lines[i] = ""
210			}
211			return lines
212		}
213	
214		// Split shortcuts into columns of maxLine items
215		columns := splitArrayIntoChunks(shortcuts, headerMinHeight)
216	
217		// Get rendered lines for each column
218		var allColumnLines [][]string
219		for i, col := range columns {
220			minH := 0
221			if i == 0 {
222				minH = headerMinHeight
223			}
224			allColumnLines = append(allColumnLines, renderShortcutsColumnLines(col, minH))
225		}
226	
227		// Normalize heights
228		for i := range allColumnLines {
229			for len(allColumnLines[i]) < headerMinHeight {
230				allColumnLines[i] = append(allColumnLines[i], "")
231			}
232		}
233	
234		// Calculate column widths
235		colWidths := make([]int, len(allColumnLines))
236		for ci, colLines := range allColumnLines {
237			for _, line := range colLines {
238				if w := lipgloss.Width(line); w > colWidths[ci] {
239					colWidths[ci] = w
240				}
241			}
242		}
243	
244		sep := "  "
245		sepRendered := theme.Bg(sep)
246	
247		// Build each row
248		result := make([]string, headerMinHeight)
249		for row := 0; row < headerMinHeight; row++ {
250			var line string
251			for ci, colLines := range allColumnLines {
252				if ci > 0 {
253					line += sepRendered
254				}
255				if row < len(colLines) {
256					line += theme.PadWithBg(colLines[row], colWidths[ci])
257				} else {
258					line += theme.EmptyLineBg(colWidths[ci])
259				}
260			}
261			// Clip to the column. PadWithBg cannot do this — it pads a short line and
262			// returns a long one untouched — and a plain slice would cut an escape
263			// sequence in half, which is the hazard Rule 122 is about. MaxWidth
264			// truncates on rune boundaries and leaves the sequences intact.
265			if col2Width > 0 {
266				line = lipgloss.NewStyle().MaxWidth(col2Width).Render(line)
267			}
268			result[row] = line
269		}
270	
271		return result
272	}
273	
274	// buildLogoLines builds the logo lines for column 3, vertically centered
275	func buildLogoLines(col3Width int) []string {
276		logoStyle := lipgloss.NewStyle().
277			Background(theme.ColorBackground).
278			Foreground(theme.ColorPrimary).
279			Bold(true)
280	
281		lines := make([]string, headerMinHeight)
282		// 5 logo lines in 7 header lines → 1 empty line top and bottom
283		offset := 1
284		for i := 0; i < headerMinHeight; i++ {
285			logoIdx := i - offset
286			if logoIdx >= 0 && logoIdx < len(logoLines) {
287				lines[i] = theme.PadWithBg(logoStyle.Render(logoLines[logoIdx]), col3Width)
288			} else {
289				lines[i] = theme.EmptyLineBg(col3Width)
290			}
291		}
292		return lines
293	}
294	
295	// renderShortcutsColumnLines renders a column of shortcuts as individual lines padded to the same width with background.
296	func renderShortcutsColumnLines(shortcuts shortcut.Shortcuts, minHeight int) []string {
297		if len(shortcuts) == 0 {
298			return nil
299		}
300	
301		lines := shortcuts.ToStrings()
302	
303		// Find max width for uniform padding
304		maxWidth := 0
305		for _, line := range lines {
306			if w := lipgloss.Width(line); w > maxWidth {
307				maxWidth = w
308			}
309		}
310	
311		// Pad each line to the same width with background
312		var result []string
313		for _, line := range lines {
314			result = append(result, theme.PadWithBg(line, maxWidth))
315		}
316	
317		// Add empty lines if minHeight required
318		for len(result) < minHeight {
319			result = append(result, theme.EmptyLineBg(maxWidth))
320		}
321	
322		return result
323	}
324	
325	func splitArrayIntoChunks(arr []shortcut.Shortcut, chunkSize int) []shortcut.Shortcuts {
326		var chunks []shortcut.Shortcuts
327		for i := 0; i < len(arr); i += chunkSize {
328			end := i + chunkSize
329			if end > len(arr) {
330				end = len(arr)
331			}
332			chunks = append(chunks, arr[i:end])
333		}
334		return chunks
335	}
336	
337	// commandLineShortcuts is the header's vocabulary while the command line owns
338	// the keyboard. It replaces the view's own: tab and enter stay in place and
339	// grey out when no row is highlighted (Rule 130).
340	func (a *App) commandLineShortcuts() shortcut.Shortcuts {
341		_, runnable := a.runnableText()
342		return shortcut.Shortcuts{
343			{Key: "↑↓", Description: "Choose"},
344			{Key: "tab", Description: "Complete", Disabled: !a.canComplete()},
345			{Key: "enter", Description: "Open", Disabled: !runnable},
346			{Key: "esc", Description: "Close"},
347		}
348	}
